#!/usr/bin/env node
/* Dehesa Index — genera data/search-index.json para el buscador global (js/search.js).
   Se ejecuta a mano cuando se añade un producto o una página (la prueba de QA avisa si el índice se queda atrás). */
import fs from 'node:fs';
import vm from 'node:vm';
const L = ['es', 'en', 'fr', 'it'];
const read = f => fs.readFileSync(f, 'utf8');
// --- datos de precios (js/data.js se carga igual que en el navegador)
const ctx = { console }; ctx.window = ctx; ctx.self = ctx; vm.createContext(ctx); vm.runInContext(read('js/data.js'), ctx);
const D = ctx.DehesaData;
const out = [];
const add = e => out.push(e);
const tri = (es, en, fr, it) => ({ es, en, fr, it });

// --- productos de la página de precios
const SYN = {
  maiz: 'corn maize mais maïs cereal grano forraje', trigo_duro: 'durum wheat blé dur grano duro semola sémola pasta macarrones cereal', trigo: 'wheat blé ble frumento pan harina cereal candeal', arroz: 'rice riz riso paddy cereal', mantequilla: 'butter beurre burro lacteo lácteo', leche_polvo: 'skim milk powder smp lait poudre latte polvere desnatada', colza: 'rapeseed canola colza oleaginosa oilseed', centeno: 'rye seigle segale cereal', cebada: 'barley orge orzo cereal cerveza malta pienso', avena: 'oats avoine avena cereal pienso', sorgo: 'sorghum sorgho milo cereal grano forraje',
  leche: 'milk lait latte lacteo lácteo dairy vaca cruda', vaca: 'vacuno beef cattle bovino bovins bovini ternera buey novillo carne res vitello manzo',
  cabra: 'goat chevre chèvre capra caprino', cerdo: 'pork hogs pig porcino cochino cochinillo porc maiale swine', cordero: 'lamb sheep ovino oveja agneau agnello mouton',
  huevos: 'eggs oeufs uova huevo gallina', pollo: 'chicken broiler poulet aves avicultura', pienso: 'feed mangime aliment compuesto racion ración',
  harina_soja: 'soja soy soybean meal tourteau farina soia proteina pienso feed', urea: 'fertilizer fertilizante abono nitrogeno nitrógeno nitrogen engrais azote',
  dap: 'fosfato fósforo phosphate phosphorus fertilizer abono engrais fosforo', potasa: 'potassium potash potasio kali fertilizer abono engrais',
  soja_grano: 'soybean soja soy soia grano grain oilseed oleaginosa',
  lenteja: 'lentil lenteja lentille lenticchia pulse legumbre',
  guisante_seco: 'peas pea guisante pois piselli pulse legumbre proteaginosa',
  lino: 'flax flaxseed linseed lino linaza lin oilseed oleaginosa',
  canola_elevador: 'canola colza rapeseed elevator bid alberta semanal weekly',
  trigo_pienso_ab: 'feed wheat trigo forrajero pienso alberta weekly',
  cebada_pienso_ab: 'feed barley cebada forrajera pienso alberta weekly',
  avena_pienso_ab: 'feed oats avena forrajera pienso alberta weekly',
  trigo_cwrs_ab: 'cwrs wheat trigo panadero red spring alberta weekly',
  lenteja_laird_ab: 'lentil laird lenteja pulse alberta weekly',
  guisante_verde_ab: 'green pea guisante verde pulse alberta weekly',
  novillo_ab: 'steers novillos cattle vacuno alberta canfax weekly',
  cerdo_ab: 'hog pig cerdo porcino cash index 100 alberta weekly',
  gas_natural: 'natural gas gas natural henry hub ttf gaz naturel gas naturale lng energia energy', petroleo_wti: 'oil crude wti texas petróleo petroleo petrole petrolio barril barrel baril energia energy', petroleo_brent: 'oil crude brent petróleo petroleo petrole petrolio barril barrel baril energia energy',
  azucar: 'sugar sucre zucchero remolacha caña beet cane', oliva: 'olive oil aceite huile olio virgen extra', diesel: 'gasoil gasóleo gasoleo fuel carburante combustible energia energía energy gazole'
};
const catLabel = (l, id) => (D.CATS[l][id] || {}).label || id;
const seen = new Set();
for (const cat of D.RAW) for (const p of cat.products) {
  const key = cat.id + ':' + p.nameKey; seen.add(key);
  add({ t: 'product', u: 'precios.html?tab=' + cat.id + '&product=' + encodeURIComponent(key), n: Object.fromEntries(L.map(l => [l, D.NAMES[l][p.nameKey]])), s: Object.fromEntries(L.map(l => [l, catLabel(l, cat.id)])), k: SYN[p.nameKey] || '' });
}
// Una entrada por pestaña de precios (Cereales, Lácteos, Fertilizantes…): «fertilizantes» o «lácteos» abren la pestaña, no solo un producto.
// Las palabras clave solo nombran lo que la pestaña tiene de verdad (la de lácteos no tiene queso, por eso no se anuncia).
const TABK = {
  cereales: 'cereales cereal grano granos grain grains céréales cereali oleaginosas oilseeds', lacteos: 'lacteos lácteos dairy laitier laitiers lattiero caseario',
  ganado: 'ganado vacuno bovino livestock cattle bétail bestiame', porcino: 'porcino cerdo pork pigs hogs porc suini', ovino: 'ovino ovinos sheep lamb corderos agneau ovins ovini',
  avicultura: 'avicultura aves poultry eggs volaille avicoltura huevos pollo', pienso: 'pienso piensos feed aliments mangimi', fertilizantes: 'fertilizantes fertilizer fertiliser engrais fertilizzanti abonos nitrogeno fosfato potasa',
  azucar: 'azucar sugar sucre zucchero', aceite: 'aceite aceites oil huile olio oliva', energia: 'energia energía energy énergie gasoil petroleo gas natural combustibles'
};
for (const cat of D.RAW) {
  const n = cat.products.length;
  add({ t: 'category', u: 'precios.html?tab=' + cat.id, n: Object.fromEntries(L.map(l => [l, catLabel(l, cat.id)])), s: tri(n + ' productos: precios y gráficos', n + ' products: prices and charts', n + ' produits : prix et graphiques', n + ' prodotti: prezzi e grafici'), k: TABK[cat.id] || '' });
}
// Frutas, hortalizas y frutos secos con ficha propia (data/fv-products.json, js/producto-hortaliza.js) y su pestaña en precios.html
{
  const FV = JSON.parse(read('data/fv-products.json'));
  const GL = { veg: tri('Hortaliza', 'Vegetable', 'Légume', 'Ortaggio'), fruit: tri('Fruta', 'Fruit', 'Fruit', 'Frutta'), nut: tri('Fruto seco', 'Nut', 'Fruit à coque', 'Frutta secca') };
  const SUBT = tri('precio semanal por país, lo que cobra el agricultor y dónde se cultiva', 'weekly price by country, what farmers get and where it is grown', 'prix hebdomadaire par pays, prix agricole et lieux de culture', 'prezzo settimanale per paese, prezzo agricolo e dove si coltiva');
  const deacc = x => x.normalize('NFD').replace(/[\u0300-\u036f]/g, '');
  for (const p of FV.products) {
    const nm = Object.fromEntries(L.map(l => [l, p.name[l] || p.name.es]));
    const kw = [...new Set(L.map(l => p.name[l]).concat(L.map(l => deacc(p.name[l] || ''))).concat(L.map(l => (p.name[l] || '') + 's')))].join(' ').toLowerCase() + ' frutas hortalizas verduras fruit vegetables precio price';
    add({ t: 'product', u: 'producto.html?p=' + p.id, n: nm, s: Object.fromEntries(L.map(l => [l, GL[p.group][l] + ' · ' + SUBT[l]])), k: kw + (p.id === 'tomate' ? ' cherry rama invernadero almeria industria pomodori' : '') });
  }
  add({ t: 'category', u: 'precios.html?tab=hortalizas&region=eu', n: tri('Frutas y hortalizas', 'Fruit and vegetables', 'Fruits et légumes', 'Frutta e verdura'), s: tri(FV.products.length + ' productos: precio semanal por país', FV.products.length + ' products: weekly price by country', FV.products.length + ' produits : prix hebdomadaire par pays', FV.products.length + ' prodotti: prezzo settimanale per paese'), k: 'frutas hortalizas verduras fruta fruit vegetables legumes ortaggi frutta verdura precios prices' });
}
add({ t: 'product', u: 'precios.html?tab=energia&product=' + encodeURIComponent('energia:diesel'), n: Object.fromEntries(L.map(l => [l, D.NAMES[l].diesel || 'Diesel'])), s: Object.fromEntries(L.map(l => [l, catLabel(l, 'energia')])), k: SYN.diesel });
for (const [id, kw] of [['seguro', 'insurance agroseguro assurance seguro agrario'], ['vino', 'wine vin vino granel'], ['madera', 'wood timber lumber bois legno'], ['energia', 'energy energia energía combustible']]) {
  add({ t: 'category', u: 'precios.html?tab=' + id, n: Object.fromEntries(L.map(l => [l, catLabel(l, id)])), s: tri('Precios', 'Prices', 'Prix', 'Prezzi'), k: kw });
}

