const CROPK = { corn: 'maiz corn maize mais', soybeans: 'soja soy soybean soia', wheat_winter: 'trigo wheat blé grano invierno winter', wheat_spring: 'trigo wheat blé grano primavera spring', cotton: 'algodon cotton coton cotone', sorghum: 'sorgo sorghum sorgho milo cereal', barley: 'cebada barley orge orzo cereal malta', rice: 'arroz rice riz riso', oats: 'avena oats avoine cereal', peanuts: 'cacahuete cacahuate mani maní peanut peanuts groundnut arachide arachidi', pasture: 'pastos pradera pasture range pastureland pâturage pascolo', sugarbeets: 'remolacha azucarera sugarbeet sugar beet betterave barbabietola', sunflower: 'girasol sunflower tournesol girasole' };
